import type {
  IsoTimestamp,
  OrgId,
  SoftDeletable,
  Timestamps,
  UserId,
} from "./common";
import type { PlanId } from "./billing";

export interface Organization extends Timestamps, SoftDeletable {
  readonly id: OrgId;
  readonly name: string;
  readonly slug: string;
  readonly ownerId: UserId;
  readonly plan: PlanId;
  readonly logoUrl: string | null;
  readonly trialEndsAt: IsoTimestamp | null;
  readonly settings: OrganizationSettings;
}

export interface OrganizationSettings {
  readonly defaultIssueStatus: string;
  readonly allowPublicProjects: boolean;
  readonly requireTwoFactor: boolean;
  readonly digestHourUtc: number;
  readonly enabledFlagOverrides: readonly string[];
}

/** Aggregate counters shown on the org dashboard and used by limit checks. */
export interface OrganizationUsage {
  readonly orgId: OrgId;
  readonly seatsUsed: number;
  readonly projectsUsed: number;
  readonly issuesUsed: number;
  readonly storageMbUsed: number;
  readonly measuredAt: IsoTimestamp;
}

/** Org record decorated with the caller's own membership, for the shell UI. */
export interface OrganizationSummary {
  readonly organization: Organization;
  readonly usage: OrganizationUsage;
  readonly memberCount: number;
  readonly projectCount: number;
}
import type {
  AttachmentId,
  IsoTimestamp,
  IssueId,
  LabelId,
  ProjectId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
];

/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export type IssuePriority = "none" | "low" | "medium" | "high" | "urgent";

export const ISSUE_PRIORITIES: readonly IssuePriority[] = [
  "none",
  "low",
  "medium",
  "high",
  "urgent",
];

export interface Issue extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: IssueId;
  readonly projectId: ProjectId;
  readonly number: number;
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly authorId: UserId;
  readonly assigneeId: UserId | null;
  readonly parentId: IssueId | null;
  readonly estimate: number | null;
  readonly dueAt: IsoTimestamp | null;
  readonly startedAt: IsoTimestamp | null;
  readonly completedAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

export interface IssueLabel extends TenantScoped {
  readonly id: LabelId;
  readonly name: string;
  readonly color: string;
  readonly description: string | null;
