/**
 * Clones a live project into a new one of the same workspace (ADR 0012). Gated
 * like a creation, plus a read of the source. Every check — including the
 * per-project issue quota for the whole batch of copies — runs before anything
 * is written, so a refused clone leaves no project and no issues behind.
 *
 * The copies are fresh issues numbered from 1 in source order; one
 * `project.cloned` event stands in for `project.created` and every
 * `issue.created` the batch would otherwise have published.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? await issueRepo.listLiveIssuesForProject(input.orgId, source.id)
    : [];

  // The clone starts empty, so the batch is checked as if each copy were
  // created in turn: 0 issues used, one requested per copy.
  if (
    wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}`,
    );
  }

  const taken = await projectRepo.listTakenProjectSlugs(input.orgId);

  const clone = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: uniqueSlug(input.slug, taken),
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const copies = await issueRepo.insertIssueCopies(
    input.orgId,
    clone.id,
    sourceIssues,
    actor.userId,
    defaultIssueStatus(org.settings.defaultIssueStatus),
  );

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: clone.id,
    sourceProjectId: source.id,
    issuesCopied: copies.length,
  });

  return clone;
}

/**
 * `OrganizationSettings.defaultIssueStatus` is stored as a plain string, so it
 * is re-validated against the enum before cloned issues start in it.
 */
function defaultIssueStatus(stored: string): IssueStatus {
  const parsed = issueStatusSchema.safeParse(stored);
  return parsed.success ? parsed.data : "backlog";
}

/** Restore does not un-archive the issues: they are restored individually. */

