import { createTenant, issueInput, useTemporaryDatabase } from "$W/tests/server/_support/fixtures";

let cleanup: () => void;
const offs: Array<() => void> = [];
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  offs.push(registerActivityListeners(), registerUsageListeners(), searchService.registerSearchListeners());
});
afterAll(() => { offs.forEach((o) => o()); cleanup(); });

describe("clone", () => {
  it("clones with issues", async () => {
    const t = await createTenant("clone1", "growth");
    const label = await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#ff0000", description: null } as never);
    const created = [];
    for (let i = 0; i < 130; i++) {
      const issue = await issueService.createIssue(t.actors.member, {
        ...issueInput(t.org.id, t.project.id, { title: "Source issue " + i, assigneeId: t.userIds.admin }),
        labelIds: i === 5 ? [label.id] : [],
        priority: "high",
        estimate: 3,
      } as never);
      created.push(issue);
    }
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: created[0].id, status: "done" });
    await issueService.archiveIssue(t.actors.admin, t.org.id, created[1].id);
    await commentRepo.insertComment?.({} as never).catch?.(() => undefined);

    const usageBefore = await usageRepo.getUsage(t.org.id);
    const events: unknown[] = [];
    const created_ev: unknown[] = [];
    const issue_ev: unknown[] = [];
    offs.push(subscribe("project.cloned", (p) => { events.push(p); }));
    offs.push(subscribe("project.created", (p) => { created_ev.push(p); }));
    offs.push(subscribe("issue.created", (p) => { issue_ev.push(p); }));

    const input = cloneProjectSchema.parse({ orgId: t.org.id, projectId: t.project.id, name: "Platform copy", slug: "platform", key: "PLC" });
    expect(input.includeIssues).toBe(true);
    const clone = await projectService.cloneProject(t.actors.member, input);
    expect(clone).toMatchObject({ name: "Platform copy", slug: "platform-2", key: "PLC", status: "active", archivedAt: null, leadId: t.project.leadId, startsAt: null, targetDate: null });
    expect(await projectRepo.findProjectById(t.org.id, clone.id)).toEqual(clone);

    const copies = await issueRepo.listLiveIssuesForProject(t.org.id, clone.id);
    expect(copies).toHaveLength(129);
    expect(copies.map((c) => c.number)).toEqual(Array.from({ length: 129 }, (_, i) => i + 1));
    expect(copies[0]).toMatchObject({ title: "Source issue 0", status: "backlog", assigneeId: null, completedAt: null, startedAt: null, authorId: t.userIds.member, priority: "high", estimate: 3 });
    expect(copies[1].title).toBe("Source issue 2");
    expect(copies[4].labelIds).toEqual([label.id]);
    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({ orgId: t.org.id, actorId: t.userIds.member, projectId: clone.id, sourceProjectId: t.project.id, issuesCopied: 129 });
    expect(created_ev).toHaveLength(0);
    expect(issue_ev).toHaveLength(0);

    const act = await listActivity(t.actors.member, { orgId: t.org.id, action: ["project.cloned"], limit: 25, cursor: null });
    expect(act.items).toHaveLength(1);
    expect(act.items[0]).toMatchObject({ action: "project.cloned", subjectKind: "project", subjectId: clone.id, projectId: clone.id, metadata: { sourceProjectId: t.project.id, issuesCopied: 129 }, actorId: t.userIds.member });
    expect(activityFilterSchema.safeParse({ orgId: t.org.id, action: ["project.cloned"], limit: 25, cursor: null }).success).toBe(true);

    const usageAfter = await usageRepo.getUsage(t.org.id);
    expect(usageAfter.projectsUsed).toBe(usageBefore.projectsUsed + 1);
    expect(usageAfter.issuesUsed).toBe(usageBefore.issuesUsed + 129);

    const hits = await searchService.search(t.actors.member, { orgId: t.org.id, q: "Source issue 129", kinds: ["issue"], limit: 25, cursor: null } as never);
    expect(hits.total).toBe(2);
    const phits = await searchService.search(t.actors.member, { orgId: t.org.id, q: "Platform copy", kinds: ["project"], limit: 25, cursor: null } as never);
    expect(phits.total).toBe(1);

    // source untouched
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(129);
    const src0 = await issueRepo.findIssueById(t.org.id, created[0].id);
    expect(src0).toMatchObject({ status: "done", assigneeId: t.userIds.admin });

    // next issue numbering continues
    const next = await issueService.createIssue(t.actors.member, issueInput(t.org.id, clone.id, { title: "After clone" }));
    expect(next.number).toBe(130);
  });

  it("refuses an oversized batch and writes nothing", async () => {
    const t = await createTenant("clone2", "free");
    for (let i = 0; i < 100; i++) await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Issue number " + i }));
    await projectService.cloneProject(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: "Fits", slug: "fits", key: "FIT", includeIssues: true }).then((c) => projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: c.id, archiveIssues: true }));
    // push source above limit via repo
    await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: "Overflow" }) as never, t.userIds.member, 999);
    const before = await projectRepo.countProjects(t.org.id, { includeArchived: true });
    await expect(projectService.cloneProject(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: "Too big", slug: "too-big", key: "TB", includeIssues: true })).rejects.toThrow(/allows/);
    expect(await projectRepo.countProjects(t.org.id, { includeArchived: true })).toBe(before);
    const without = await projectService.cloneProject(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: "Empty", slug: "empty", key: "EMP", includeIssues: false });
    expect(await issueRepo.countIssues(t.org.id, without.id, { includeArchived: true })).toBe(0);
    await expect(projectService.cloneProject(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: "Third", slug: "third", key: "THI", includeIssues: false })).rejects.toThrow(/allows 2 projects/);
    await expect(projectService.cloneProject(t.actors.viewer, { orgId: t.org.id, projectId: t.project.id, name: "View", slug: "view", key: "VW", includeIssues: false })).rejects.toThrow();
  });
});
